import{_ as t}from"./chunks/mac-security-settings.DOF-7oNi.js";import{_ as i,o as n,c as s,a0 as a}from"./chunks/framework.CQlhmJfM.js";const m=JSON.parse('{"title":"Häufiges macOS-Installationsproblem - \\"App ist beschädigt\\" Lösung","titleTemplate":false,"description":"Tabs‑Multitasking als Kern, vereint Plugin‑Ökosystem, Native‑Funktionen und Desktop‑Runtime. Jedes Tool wird zu einem komposierbaren KI‑Workflow‑Modul.","frontmatter":{"head":[["meta",{"name":"keywords","content":"OTools,KI Workflow Plattform,Desktop Werkzeuge,Plugin Ökosystem,Tabs Multitasking,Entwickler Werkzeugkasten"}],["meta",{"name":"author","content":"OTools"}],["link",{"rel":"canonical","href":"https://ootools.github.io/otools-website/de/guide/mac-installation-issue"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:site_name","content":"OTools"}],["meta",{"property":"og:title","content":"Häufiges macOS-Installationsproblem - \\"App ist beschädigt\\" Lösung"}],["meta",{"property":"og:description","content":"Tabs‑Multitasking als Kern, vereint Plugin‑Ökosystem, Native‑Funktionen und Desktop‑Runtime. Jedes Tool wird zu einem komposierbaren KI‑Workflow‑Modul."}],["meta",{"property":"og:url","content":"https://ootools.github.io/otools-website/de/guide/mac-installation-issue"}],["meta",{"property":"og:image","content":"https://ootools.github.io/otools-website/otools-logo.svg"}],["meta",{"property":"og:image:width","content":"2880"}],["meta",{"property":"og:image:height","content":"1800"}],["meta",{"property":"og:locale","content":"de_DE"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Häufiges macOS-Installationsproblem - \\"App ist beschädigt\\" Lösung"}],["meta",{"name":"twitter:description","content":"Tabs‑Multitasking als Kern, vereint Plugin‑Ökosystem, Native‑Funktionen und Desktop‑Runtime. Jedes Tool wird zu einem komposierbaren KI‑Workflow‑Modul."}],["meta",{"name":"twitter:image","content":"https://ootools.github.io/otools-website/otools-logo.svg"}],["link",{"rel":"alternate","type":"text/plain","href":"/otools-website/llms.txt","title":"OTools 站点说明（AI 检索）"}],["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"TechArticle\\",\\"headline\\":\\"Häufiges macOS-Installationsproblem - \\\\\\"App ist beschädigt\\\\\\" Lösung\\",\\"description\\":\\"Tabs‑Multitasking als Kern, vereint Plugin‑Ökosystem, Native‑Funktionen und Desktop‑Runtime. Jedes Tool wird zu einem komposierbaren KI‑Workflow‑Modul.\\",\\"url\\":\\"https://ootools.github.io/otools-website/de/guide/mac-installation-issue\\",\\"inLanguage\\":\\"de-DE\\",\\"author\\":{\\"@type\\":\\"Organization\\",\\"name\\":\\"OTools\\"}}"]]},"headers":[],"relativePath":"de/guide/mac-installation-issue.md","filePath":"de/guide/mac-installation-issue.md"}'),o={name:"de/guide/mac-installation-issue.md"};function l(r,e,u,d,h,p){return n(),s("div",null,[...e[0]||(e[0]=[a('<h1 id="haufiges-macos-installationsproblem-app-ist-beschadigt-losung" tabindex="-1">Häufiges macOS-Installationsproblem - &quot;App ist beschädigt&quot; Lösung <a class="header-anchor" href="#haufiges-macos-installationsproblem-app-ist-beschadigt-losung" aria-label="Permalink to &quot;Häufiges macOS-Installationsproblem - &quot;App ist beschädigt&quot; Lösung&quot;">​</a></h1><p>Beim Installieren von OTools oder anderen Drittanbieter-Anwendungen unter macOS kann es vorkommen, dass Sie eine Meldung ähnlich wie &quot;xxx.app ist beschädigt, kann nicht geöffnet werden, Sie sollten es in den Papierkorb verschieben&quot; sehen. Dies liegt in der Regel an den Sicherheitseinstellungen von macOS.</p><h2 id="warum-tritt-dieses-problem-auf" tabindex="-1">Warum tritt dieses Problem auf? <a class="header-anchor" href="#warum-tritt-dieses-problem-auf" aria-label="Permalink to &quot;Warum tritt dieses Problem auf?&quot;">​</a></h2><p>macOS hat im Vergleich zu Windows eine sehr strenge Kontrolle über Programme. Nicht aus dem App Store stammende Apps zeigen während der Installation häufig Meldungen wie &quot;xxx.app ist beschädigt&quot;. Seit macOS 10.15 hat Apple die Berechtigungen für unsignierte Anwendungen weiter eingeschränkt, wodurch diese Probleme häufiger auftreten.</p><h2 id="losungen" tabindex="-1">Lösungen <a class="header-anchor" href="#losungen" aria-label="Permalink to &quot;Lösungen&quot;">​</a></h2><h3 id="methode-1-einstellung-zum-zulassen-von-apps-aus-beliebigen-quellen" tabindex="-1">Methode 1: Einstellung zum Zulassen von Apps aus &quot;Beliebigen Quellen&quot; <a class="header-anchor" href="#methode-1-einstellung-zum-zulassen-von-apps-aus-beliebigen-quellen" aria-label="Permalink to &quot;Methode 1: Einstellung zum Zulassen von Apps aus &quot;Beliebigen Quellen&quot;&quot;">​</a></h3><ol><li>Öffnen Sie &quot;Systemeinstellungen -&gt; Sicherheit und Datenschutz -&gt; Allgemein&quot;</li><li>Überprüfen Sie, ob bei der Option &quot;Apps heruntergeladen von&quot; bereits die Option &quot;Beliebig&quot; aktiviert ist</li><li>Falls nicht aktiviert, klicken Sie unten links auf das kleine Schlosssymbol zum Entsperren und wählen Sie dann &quot;Beliebig&quot;</li></ol><p><img src="'+t+'" alt=""></p><p>Wenn Sie die Option &quot;Beliebig&quot; in den Einstellungen nicht sehen, öffnen Sie das Terminal und geben Sie folgenden Befehl ein:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> spctl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --master-disable</span></span></code></pre></div><p>Geben Sie Ihr Computer-Anmeldekennwort ein und drücken Sie Enter. Danach sehen Sie in den Einstellungen die Option &quot;Beliebig&quot;.</p><p>Normalerweise kann die App nach dieser Einstellung normal installiert werden. Wenn Ihre macOS-Version jedoch neuer ist, müssen Sie möglicherweise trotzdem die nächste Methode versuchen.</p><h3 id="methode-2-umgehen-der-gatekeeper-authentifizierung-von-apple" tabindex="-1">Methode 2: Umgehen der Gatekeeper-Authentifizierung von Apple <a class="header-anchor" href="#methode-2-umgehen-der-gatekeeper-authentifizierung-von-apple" aria-label="Permalink to &quot;Methode 2: Umgehen der Gatekeeper-Authentifizierung von Apple&quot;">​</a></h3><p>Falls Methode 1 das Problem immer noch nicht löst, können Sie folgende Schritte versuchen:</p><ol><li>Öffnen Sie das Terminal</li><li>Geben Sie den folgenden Befehl ein, drücken Sie aber noch nicht Enter:</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> xattr</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -rd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> com.apple.quarantine</span></span></code></pre></div><ol start="3"><li>Suchen Sie im Finder den Ordner &quot;Programme&quot; und finden Sie dort OTools.app</li><li>Ziehen Sie OTools.app in das Terminalfenster, wodurch automatisch der Pfad der App an den Befehl angehängt wird</li><li>Drücken Sie Enter, geben Sie Ihr Passwort ein, danach können Sie die App direkt ausführen</li></ol><h3 id="methode-3-rechtsklick-zum-offnen-geeignet-fur-die-erstinstallation" tabindex="-1">Methode 3: Rechtsklick zum Öffnen (geeignet für die Erstinstallation) <a class="header-anchor" href="#methode-3-rechtsklick-zum-offnen-geeignet-fur-die-erstinstallation" aria-label="Permalink to &quot;Methode 3: Rechtsklick zum Öffnen (geeignet für die Erstinstallation)&quot;">​</a></h3><p>Für Erstinstallationen können Sie auch Folgendes versuchen:</p><ol><li>Suchen Sie OTools.app im Finder</li><li>Klicken Sie mit der rechten Maustaste (oder halten Sie die Steuerungstaste gedrückt und klicken Sie)</li><li>Wählen Sie &quot;Öffnen&quot;</li><li>Klicken Sie im Sicherheitswarnfenster auf &quot;Öffnen&quot;</li></ol><h2 id="wichtige-hinweise" tabindex="-1">Wichtige Hinweise <a class="header-anchor" href="#wichtige-hinweise" aria-label="Permalink to &quot;Wichtige Hinweise&quot;">​</a></h2><ul><li>OTools ist eine legitime Desktop-Anwendung, die mit dem Tauri Framework erstellt wurde</li><li>Ihr Computer ist nicht durch Malware beeinträchtigt</li><li>Dieses Problem wird durch die Sicherheitsrichtlinien von Apple verursacht, nicht durch die Anwendung selbst</li></ul>',22)])])}const k=i(o,[["render",l]]);export{m as __pageData,k as default};
